#pragma once
// Engine sound from a real recording (header only, shared by the ESP32 firmware and the host
// preview tool tools/render_engine_real.cpp).
//
// The recording (START_WARM, generated by tools/make_user_sounds.py into user_sounds.h) is
// played once from the beginning (engine starting), then the steady idle part LOOP_START ..
// LOOP_END repeats with an equal-power crossfade. In the loop, RPM raises the playback rate a
// little and the volume. Throttle is ignored during the start-up part.
#include <stdint.h>
#include <math.h>
#include "user_sounds.h"

#ifndef REAL_RATE_RANGE
#define REAL_RATE_RANGE 0.40f    // playback rate goes 1.0 .. 1.0+RANGE with RPM
#endif
#ifndef REAL_GAIN
#define REAL_GAIN 1.3f           // recording peaks at about 0.7 of full scale
#endif
#ifndef REAL_XFADE
#define REAL_XFADE 2205          // loop crossfade length in samples (100 ms)
#endif
#ifndef REAL_START_ENABLED
#define REAL_START_ENABLED 1     // 0: skip the start-up part and begin in the idle loop
#endif

class EngineReal {
 public:
  float rpm = 0.0f;
  float pos = REAL_START_ENABLED ? 0.0f : (float)LOOP_START;

  // Call once per audio block (about every 5.8 ms) with throttle 0..1.
  void block(float throttle) {
    float k = throttle > rpm ? 0.02f : 0.008f;
    rpm += (throttle - rpm) * k;
    if (pos < (float)LOOP_START) {   // starting up: natural speed and level
      rate = 1.0f;
      vol = REAL_GAIN;
    } else {
      rate = 1.0f + REAL_RATE_RANGE * rpm;
      vol = REAL_GAIN * (0.65f + 0.35f * rpm);
    }
  }

  // One output sample in -1..1 (apply the master volume outside).
  float sample() {
    float s = read(pos) * vol;
    pos += rate;
    if (pos >= (float)LOOP_END) pos -= (float)(LOOP_END - LOOP_START);
    return s;
  }

  bool starting() const { return pos < (float)LOOP_START; }

 private:
  float rate = 1.0f;
  float vol = REAL_GAIN;

  static float at(int i) { return ((int)START_WARM[i] - 128) * (1.0f / 128.0f); }
  static float lerpAt(float p) {
    int i = (int)p;
    float f = p - i;
    return at(i) + (at(i + 1) - at(i)) * f;
  }
  static float read(float p) {
    float a = lerpAt(p);
    const float xf = (float)REAL_XFADE;
    const float end = (float)LOOP_END;
    if (p >= end - xf) {
      float t = (p - (end - xf)) / xf;                 // 0..1 across the crossfade
      float b = lerpAt(p - (float)(LOOP_END - LOOP_START));
      a = a * cosf(t * 1.5707963f) + b * sinf(t * 1.5707963f);   // equal power
    }
    return a;
  }
};
